-- FIXTURE SYNTHÉTIQUE DE TEST — NE REPRÉSENTE PAS LA PRODUCTION.
-- À exécuter uniquement dans PostgreSQL jetable via le harness.
-- Les identifiants et libellés sont artificiels. Cette fixture valide le mécanisme
-- d'empreinte, pas la compatibilité avec le schéma historique réel de DEKK FOOD.

CREATE SCHEMA IF NOT EXISTS public;

CREATE SEQUENCE public.restaurants_id_seq
  AS integer START WITH 1000 INCREMENT BY 1;

CREATE TABLE public.restaurants (
  id integer PRIMARY KEY DEFAULT nextval('public.restaurants_id_seq'),
  name text NOT NULL,
  created_at timestamptz NOT NULL DEFAULT now()
);
ALTER SEQUENCE public.restaurants_id_seq OWNED BY public.restaurants.id;

CREATE TABLE public.restaurant_menus (
  id integer GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  restaurant_id integer NOT NULL
    REFERENCES public.restaurants(id) ON DELETE CASCADE,
  name text NOT NULL,
  UNIQUE (restaurant_id, name)
);

CREATE TABLE public.restaurant_reviews (
  id integer GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  restaurant_id integer NOT NULL
    REFERENCES public.restaurants(id) ON DELETE CASCADE,
  rating integer NOT NULL CHECK (rating BETWEEN 1 AND 5),
  body text NOT NULL
);

INSERT INTO public.restaurants (id, name, created_at)
VALUES (42, 'Fixture synthétique — restaurant témoin',
        '2026-01-01T00:00:00Z');

INSERT INTO public.restaurant_menus (id, restaurant_id, name)
VALUES (7, 42, 'Menu synthétique');

INSERT INTO public.restaurant_reviews (id, restaurant_id, rating, body)
VALUES (9, 42, 5, 'Avis artificiel pour test d''intégrité');

CREATE FUNCTION public.synthetic_history_marker()
RETURNS integer
LANGUAGE sql
IMMUTABLE
AS $$ SELECT 42 $$;

CREATE FUNCTION public.synthetic_review_guard()
RETURNS trigger
LANGUAGE plpgsql
AS $$
BEGIN
  IF NEW.rating < 1 OR NEW.rating > 5 THEN
    RAISE EXCEPTION 'rating hors limites';
  END IF;
  RETURN NEW;
END;
$$;

CREATE TRIGGER synthetic_review_guard_trigger
BEFORE INSERT OR UPDATE ON public.restaurant_reviews
FOR EACH ROW EXECUTE FUNCTION public.synthetic_review_guard();

-- La RLS est activée sans dépendre de rôles Supabase spécifiques.
ALTER TABLE public.restaurant_reviews ENABLE ROW LEVEL SECURITY;
CREATE POLICY synthetic_review_read_policy
  ON public.restaurant_reviews
  FOR SELECT
  USING (rating >= 1);
